(function () {
  "use strict";

  var SRC = "http://192.168.1.10:8000/blocker.min.js";
  var BUST = true;

  var TAG = "color:#fff;background:#0ea5e9;padding:1px 6px;border-radius:3px;font-weight:600";
  var PLAIN = "color:inherit;background:none;font-weight:normal";

  function say() {
    var a = [].slice.call(arguments);
    console.log.apply(console, ["%cloader%c " + a.shift(), TAG, PLAIN].concat(a));
  }

  var url = SRC + (BUST ? (SRC.indexOf("?") === -1 ? "?" : "&") + "t=" + Date.now() : "");

  say("start on " + location.hostname + ", readyState=" + document.readyState);
  say("loading", url);

  var s = document.createElement("script");
  s.src = url;
  s.async = false;

  s.onload = function () {
    s.remove();
    say("loaded, window.__blocker is", typeof window.__blocker);
  };

  s.onerror = function () {
    s.remove();
    var meta = document.querySelector('meta[http-equiv="Content-Security-Policy" i]');
    console.error("%cloader%c script[src] blocked or unreachable", TAG, PLAIN);
    console.error(
      "%cloader%c CSP in meta:",
      TAG,
      PLAIN,
      meta ? meta.getAttribute("content") : "(none; check response headers in Network tab)"
    );
  };

  (document.head || document.documentElement).appendChild(s);
})();
